//! 🧪️ Original ranked sources and immutable key roots preserve exact typed custody under every paid frontier.
use super::*;
use crate::{list::persistent::{PersistentList,PersistentListBuilder},named_edit::{VecRankedKeys,PersistentRankedKeys,contiguous_named_key_demand,observe_contiguous_named_key},retained_clone::{RetainedCloneSource,RetainedOwnedProjection},retirement::controlled::ControlledRetirement};
#[derive(crate::RetireOwned)]struct Row{key:String}
impl Clone for Row{fn clone(&self)->Self{panic!("ranked named rows must retain their original payload")}}
#[path="../♻️transfer/🧪️tests/🦀️.rs"]mod transfer;
fn key(row:&Row)->&str{&row.key}
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn heap<T>(run:impl FnOnce()->T)->(T,(usize,usize)){crate::observe_retirement_allocations(run)}
fn exact<T>(run:impl FnOnce()->T,receipt:impl FnOnce(&T)->RetainedCloneProgress)->(T,usize,usize){let(value,bytes)=heap(run);let p=receipt(&value);assert_eq!(bytes,(p.retained_capacity_bytes,p.released_bytes));(value,bytes.0,bytes.1)}
fn denies(d:RetirementDemand)->Vec<RetainedCloneGrant>{let g=grant(d);let mut rows=vec![RetainedCloneGrant{maximum_items:0,..g}];if d.copy_bytes>0{rows.push(RetainedCloneGrant{maximum_copy_bytes:0,..g});}if d.capacity_bytes>0{rows.push(RetainedCloneGrant{maximum_capacity_bytes:0,..g});}if d.release_bytes>0{rows.push(RetainedCloneGrant{maximum_release_bytes:0,..g});}if d.depth>0{rows.push(RetainedCloneGrant{maximum_depth:0,..g});}rows}
fn source<T:RetireOwned+Sync+'static>(value:T)->RetainedCloneSource<T>{let birth=RetainedCloneSource::<T>::owned_constructor_demand::<()>();RetainedCloneSource::admit_owned(value,(),grant(RetirementDemand{copy_bytes:RetainedCloneSource::<T>::constructor_copy_bytes(),capacity_bytes:birth.capacity_bytes,depth:birth.depth,..Default::default()})).map_err(|(e,..)|e).unwrap().0}
fn close_source<T:RetireOwned+Sync+'static>(source:&mut RetainedCloneSource<T>){while !source.terminal_is_empty(){let d=RetirementDemand{copy_bytes:source.next_close_copy_byte_demand().unwrap(),capacity_bytes:source.next_close_capacity_byte_demand(4096).unwrap(),release_bytes:source.next_close_release_byte_demand().unwrap(),depth:source.next_close_depth_demand().unwrap()};exact(||source.close_step(grant(d)).unwrap(),|s|s.progress());}}
fn drain<T:RetireOwned>(value:T){let mut owner=ControlledRetirement::new(value).map_err(|(e,_)|e).unwrap();while !owner.terminal_is_empty(){let d=owner.next_demand(4096).unwrap();exact(||owner.step(grant(d)).unwrap(),|s|s.progress());}}
fn close_preparation(owner:&mut NamedKeyIndexPreparation,mut births:usize,mut releases:usize){owner.begin_close();while !owner.terminal_is_empty(){let d=owner.close_demand(4096).unwrap();for denied in denies(d){let(s,bytes)=heap(||owner.close_step(denied).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(bytes,(0,0));assert_eq!(owner.close_demand(4096).unwrap(),d);}let(_,b,r)=exact(||owner.close_step(grant(d)).unwrap(),|s|s.progress());births+=b;releases+=r;}assert_eq!(births,releases);assert_eq!(heap(||{}).1,(0,0));}
fn close_index(index:&mut AdmittedNamedKeyIndex)->(usize,usize){let mut totals=(0,0);index.begin_close();while !index.terminal_is_empty(){let d=index.close_demand(4096).unwrap();for denied in denies(d){let(s,bytes)=heap(||index.close_step(denied).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(bytes,(0,0));assert_eq!(index.close_demand(4096).unwrap(),d);}let(_,b,r)=exact(||index.close_step(grant(d)).unwrap(),|s|s.progress());totals.0+=b;totals.1+=r;}totals}
fn close_plan(plan:&mut NamedEditPlan){plan.begin_close();while !plan.terminal_is_empty(){let d=plan.close_demand(4096).unwrap();for denied in denies(d){let(s,bytes)=heap(||plan.close_step(denied).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(bytes,(0,0));assert_eq!(plan.close_demand(4096).unwrap(),d);}exact(||plan.close_step(grant(d)).unwrap(),|s|s.progress());}}
fn admit<S:NamedRankedSource>(source:&S)->AdmittedNamedKeyIndex{let mut owner=NamedKeyIndexPreparation::new(source.len(),grant(NamedKeyIndexPreparation::constructor_demand())).unwrap().unwrap();loop{let d=owner.demand(source,4096).unwrap();let(s,..)=exact(||owner.advance(source,grant(d)).unwrap(),|s|s.progress());if matches!(s,NamedEditStep::Admitted(_)){break;}assert!(!matches!(s,NamedEditStep::Refused(..)));}let d=owner.take_demand().unwrap();let((index,_),..)=exact(||owner.take(grant(d)).unwrap().unwrap(),|(_,p)|*p);owner.begin_close();assert!(owner.terminal_is_empty());assert_eq!(heap(||drop(owner)).1,(0,0));index}
struct Query<'a>{len:usize,key:&'a str}
impl NamedEditSource for Query<'_>{
 fn shape(&self)->IndexedEditShape{IndexedEditShape{base_len:self.len,removed:0,modified:1,added:0}}
 fn key_demand(&self,lane:NamedEditLane,ordinal:usize)->Result<RetirementDemand,ValueError>{if lane!=NamedEditLane::Modified||ordinal!=0{return Err(invalid());}Ok(contiguous_named_key_demand(self))}
 fn observe_key(&self,lane:NamedEditLane,ordinal:usize,g:RetainedCloneGrant)->Result<Option<(&str,RetainedCloneProgress)>,ValueError>{Ok(observe_contiguous_named_key(self.key_demand(lane,ordinal)?,g,||self.key))}
 fn added_index(&self,_:usize)->usize{unreachable!("original named lookup has no additions")}
}
fn lookup<S:NamedRankedSource>(source:&S,index:&AdmittedNamedKeyIndex,key:&str)->(Option<usize>,usize){let d=index.project_demand(source).unwrap();let((mut alias,_),..)=exact(||index.project(source,grant(d)).unwrap().unwrap(),|(_,p)|*p);let mut slot=Some(alias);let d=NamedEditPlan::indexed_constructor_demand();let mut plan=NamedEditPlan::new_indexed(Query{len:source.len(),key}.shape(),&mut slot,grant(d)).unwrap().unwrap();assert!(slot.is_none());let query=Query{len:source.len(),key};let input=IndexedNamedSource::new(source,&query,index).unwrap();let mut capacity=0;while !plan.settled(){let d=plan.demand(&input,4096).unwrap();for denied in denies(d){let(s,bytes)=heap(||plan.advance(&input,denied).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(bytes,(0,0));assert_eq!(plan.demand(&input,4096).unwrap(),d);}let(s,b,..)=exact(||plan.advance(&input,grant(d)).unwrap(),|s|s.progress());capacity+=b;assert!(s.progress().copied_bytes<=d.copy_bytes);}let result=if plan.ready(){let d=plan.modified_index_demand(0).unwrap();let((rank,p),bytes)=heap(||plan.observe_modified_index(0,grant(d)).unwrap().unwrap());assert_eq!(bytes,(0,0));assert_eq!(p.copied_bytes,d.copy_bytes);Some(rank)}else{assert_eq!(plan.fault(),Some(NamedEditFault::MissingModified));None};close_plan(&mut plan);assert_eq!(heap(||drop(plan)).1,(0,0));(result,capacity)}
fn persistent(keys:impl IntoIterator<Item=String>,len:usize)->PersistentList<Row>{let mut builder=PersistentListBuilder::new(len,grant(PersistentListBuilder::<Row>::constructor_demand())).unwrap().unwrap();for text in keys{while !builder.accepts_row(){let d=builder.demand().unwrap();exact(||builder.advance(grant(d)).unwrap(),|s|s.progress());}let mut row=Some(SealedShared::admit(Row{key:text},SharedIssuer::owned(),grant(RetirementDemand{capacity_bytes:SealedShared::<Row>::birth_bytes(),depth:1,..Default::default()})).map_err(|(e,_)|e).unwrap().0);let d=builder.adopt_demand().unwrap();builder.adopt(&mut row,grant(d)).unwrap().unwrap();}let d=builder.finish_demand().unwrap();builder.finish(grant(d)).unwrap().unwrap();while !builder.output_ready(){let d=builder.demand().unwrap();exact(||builder.advance(grant(d)).unwrap(),|s|s.progress());}let d=builder.take_demand().unwrap();let root=builder.take(grant(d)).unwrap().unwrap().0;builder.begin_close();while !builder.terminal_is_empty(){let d=builder.close_demand(4096).unwrap();exact(||builder.close_step(grant(d)).unwrap(),|s|s.progress());}root}
#[test]
fn admitted_named_index_preserves_original_opaque_keys_ranked_sources_and_cancelled_custody(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();
 for row in fixture["cases"].as_array().unwrap(){let keys=row["keys"].as_array().unwrap();for body in fixture["bodyBytes"].as_array().unwrap(){for cut in fixture["cancelCuts"].as_array().unwrap().iter().map(|cut|Some(cut.as_u64().unwrap())).chain(std::iter::once(None)){
  let mut original=source(keys.iter().map(|key|Row{key:key.as_str().unwrap().to_owned()}).collect::<Vec<_>>());let input=VecRankedKeys{original:original.borrow(),key};let pointers=input.original.get().iter().map(|row|(row.key.as_ptr(),row.key.len())).collect::<Vec<_>>();let mut owner=NamedKeyIndexPreparation::new(keys.len(),grant(NamedKeyIndexPreparation::constructor_demand())).unwrap().unwrap();let mut turns=0;let mut born=0;let mut released=0;
  while !owner.output_ready()&&owner.fault().is_none()&&cut.is_none_or(|cut|turns<cut){let d=owner.demand(&input,body.as_u64().unwrap()as usize).unwrap();for denied in denies(d){let(s,bytes)=heap(||owner.advance(&input,denied).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(bytes,(0,0));assert_eq!(owner.demand(&input,body.as_u64().unwrap()as usize).unwrap(),d);}let(_,b,r)=exact(||owner.advance(&input,grant(d)).unwrap(),|s|s.progress());born+=b;released+=r;turns+=1;assert!(turns<1000000);}
  if cut.is_none(){assert_eq!(owner.output_ready(),!row["expected"].is_null());if owner.output_ready(){let d=owner.take_demand().unwrap();let((mut index,_),..)=exact(||owner.take(grant(d)).unwrap().unwrap(),|(_,p)|*p);for(i,text)in row["queries"].as_array().unwrap().iter().enumerate(){assert_eq!(lookup(&input,&index,text.as_str().unwrap()).0,row["expected"][i].as_u64().map(|n|n as usize));}let mut foreign=source(keys.iter().map(|key|Row{key:key.as_str().unwrap().to_owned()}).collect::<Vec<_>>());let other=VecRankedKeys{original:foreign.borrow(),key};assert!(index.check_source(&other).is_err());assert!(index.project_demand(&other).is_err());close_source(&mut foreign);let(b,r)=close_index(&mut index);born+=b;released+=r;assert_eq!(heap(||drop(index)).1,(0,0));}else{assert_eq!(owner.fault(),Some(NamedEditFault::DuplicateBase));}}
  assert_eq!(input.original.get().iter().map(|row|(row.key.as_ptr(),row.key.len())).collect::<Vec<_>>(),pointers);close_preparation(&mut owner,born,released);assert_eq!(heap(||drop(owner)).1,(0,0));close_source(&mut original);
 }}}
 println!("[DEBUG] Original admitted named roots preserve SQLite opaque-key/rank semantics, exact field addresses, five denied currencies, foreign-root refusal and all declared paid admission cuts");
}
#[test]
fn admitted_named_index_reuses_persistent_originals_without_base_allocation_or_resorting(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();
 for len in fixture["lengths"].as_array().unwrap(){let len=len.as_u64().unwrap()as usize;let mut original=source(persistent((0..len).map(|i|format!("key{:08}",len-i)),len));let input=PersistentRankedKeys{original:original.borrow(),key};let address=input.original.get().get(len-1).unwrap().key.as_ptr();let mut index=admit(&input);for rank in [0,len/2,len-1]{let query=format!("key{:08}",len-rank);let(result,capacity)=lookup(&input,&index,&query);assert_eq!(result,Some(rank));assert!(capacity<=size_of::<usize>()+size_of::<crate::IndexedEditEntry>()*2,"sparse lookup allocated base coordinates");}assert_eq!(input.original.get().get(len-1).unwrap().key.as_ptr(),address);close_index(&mut index);assert_eq!(heap(||drop(index)).1,(0,0));close_source(&mut original);println!("[DEBUG] Immutable ranked named index length={len} reuses original row/key paths and admits only sparse coordinate allocations");}
}
